-- -----------------------------------
-- Table structure for `footage_details_available_start_zip`
-- -----------------------------------

DROP TABLE IF EXISTS `footage_details_available_start_zip`;
CREATE TABLE `footage_details_available_start_zip` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `year` varchar(150) CHARACTER SET utf8mb4 NOT NULL DEFAULT '2025',
  `month` varchar(50) CHARACTER SET utf8mb4 NOT NULL,
  `dt` varchar(50) CHARACTER SET utf8mb4 NOT NULL,
  `atmid` text CHARACTER SET utf8mb4 NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `created_by` int(11) NOT NULL,
  `footage_type` varchar(100) CHARACTER SET utf8mb4 NOT NULL,
  `footage_status` int(11) NOT NULL DEFAULT '0',
  `ftp_server_path` longtext CHARACTER SET utf8mb4 NOT NULL,
  `local_path` longtext CHARACTER SET utf8mb4 NOT NULL,
  `remarks` text CHARACTER SET utf8mb4 NOT NULL,
  `attempts` int(11) NOT NULL DEFAULT '0',
  `total_video_length` double(10,3) NOT NULL DEFAULT '0.000',
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=28509 DEFAULT CHARSET=latin1;

